// ────────────────────────────────────────────────
// 링크 설정
// ────────────────────────────────────────────────
const LINK_MISSION_BOARD   = "https://docs.google.com/spreadsheets/d/1IYO9IM74kXbzGOfre2B64ur9vvN2wErwK0wJn0A5wpQ/edit?gid=1000209332#gid=1000209332";
const LINK_KDT_DASHBOARD   = "https://docs.google.com/spreadsheets/d/11rR6vllVDMPN_zg5xjIPzj4DlI31an9_GKvuHitmR9U/edit?gid=0#gid=0";
const LINK_NOTION          = "https://www.notion.so/teamsparta/1df2dc3ef5148007a54cf6d316641228?v=2e22dc3ef51480eb9e75000c4405af7a&p=2dc2dc3ef51480c9a05bea7323eae4c8&pm=s";

// ────────────────────────────────────────────────
// D-day 계산 (Google Sheets 노드에서 받은 데이터)
//
// 구조 문제: 스프레드시트의 좌측(세션 데이터)과 우측(트랙 요약) 두 테이블이
// 같은 행을 공유하여, '트랙 정보' 컬럼이 우측 요약 트랙명을 읽어버림.
// → 해결: 스프레드시트 섹션 순서를 하드코딩하고, 섹션 헤더 행을 감지해
//   sectionIndex로 올바른 트랙명을 결정.
// ────────────────────────────────────────────────
const today = new Date();
today.setHours(0, 0, 0, 0);

// 좌측 데이터 테이블에 나타나는 트랙 섹션 순서
const TRACK_ORDER = [
  '단기심화Spring',
  'Unreal',
  'QAQC',
  'PM',
  'ai그래픽디자이너',
  '커머스스프링',
  'ai디지털마케터',
  '26 1H 승인',
  'AI Top-tier',
];

let sectionIndex = -1;
const upcoming = [];

for (const row of $input.all()) {
  const d    = row.json;
  const col4 = String(d['col_4'] || '').trim();
  const jong = String(d['종강']  || '').trim();

  // 새 섹션 헤더 감지
  // - "정원 : X" 행 → 단기심화Spring ~ ai디지털마케터 (7개 섹션)
  // - "X시간으로 가정" 행 → 26 1H 승인, AI Top-tier (2개 섹션)
  if (col4.startsWith('정원') || jong.includes('시간으로 가정')) {
    sectionIndex++;
    continue; // 헤더 행은 날짜 없음 → 스킵
  }

  if (sectionIndex < 0 || sectionIndex >= TRACK_ORDER.length) continue;
  const trackName = TRACK_ORDER[sectionIndex];

  // 회차 (col_3 이 숫자일 때만)
  const col3  = d['col_3'];
  const round = (col3 !== null && col3 !== undefined &&
                 col3 !== '' && !isNaN(Number(col3)))
    ? Number(col3)
    : null;

  // 모집 시작일 파싱 ("2026. 2. 23" 형식)
  const startRaw = (d['개강 전'] || '').trim();
  if (!startRaw || !/^\d/.test(startRaw)) continue;

  const parts = startRaw.split('.').map(s => s.trim()).filter(Boolean);
  if (parts.length !== 3) continue;

  const startDate = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
  startDate.setHours(0, 0, 0, 0);
  if (isNaN(startDate.getTime())) continue;

  const diff = Math.round((startDate - today) / 86400000);
  if (diff >= 0 && diff <= 30) {
    upcoming.push({ trackName, round, diff });
  }
}

upcoming.sort((a, b) => a.diff - b.diff);

const ddayText = upcoming.length > 0
  ? upcoming.map(({ trackName, round, diff }) => {
      const label    = diff === 0 ? '*D-DAY* 🔥' : `D-${diff}`;
      const roundStr = round !== null ? ` (${round}기)` : '';
      return `• ${label}  ${trackName}${roundStr}`;
    }).join('\n')
  : '_30일 이내 모집 예정 트랙 없음_';

// ────────────────────────────────────────────────
// RSS 수집
// ────────────────────────────────────────────────
const FEEDS = [
  { name: "전자신문",     url: "https://www.etnews.com/rss/" },
  { name: "ZDNet Korea", url: "https://zdnet.co.kr/rss/rss.aspx" },
  { name: "블로터",       url: "https://www.bloter.net/feed" },
  { name: "IT조선",       url: "https://it.chosun.com/rss/data/it.xml" },
];
const KEYWORDS = [
  "KDT", "내일배움", "부트캠프", "디지털 교육", "AI 교육",
  "코딩 교육", "취업 연계", "훈련 기관", "HRD", "K-Digital",
  "기술 교육", "디지털 훈련", "직업훈련", "재직자 훈련",
];

const articles = [];
for (const feed of FEEDS) {
  try {
    const resp = await fetch(feed.url, {
      headers: { "User-Agent": "MorningBriefingBot/1.0" },
      signal: AbortSignal.timeout(8000),
    });
    const raw = await resp.text();
    const items = raw.match(/<item>([\s\S]*?)<\/item>/g) || [];
    for (const item of items) {
      const title = (
        item.match(/<title><!\[CDATA\[([\s\S]*?)\]\]><\/title>/) ||
        item.match(/<title>([^<]*)<\/title>/)
      )?.[1]?.trim() ?? "";
      const link = (
        item.match(/<link>([^<]+)<\/link>/) ||
        item.match(/<guid[^>]*>(https?:\/\/[^<]+)<\/guid>/)
      )?.[1]?.trim() ?? "";
      const desc = (
        item.match(/<description><!\[CDATA\[([\s\S]*?)\]\]><\/description>/) ||
        item.match(/<description>([^<]*)<\/description>/)
      )?.[1] ?? "";
      if (KEYWORDS.some(kw => (title + desc).toLowerCase().includes(kw.toLowerCase()))) {
        articles.push({ title, link, source: feed.name });
      }
    }
  } catch (_) {}
}

// ────────────────────────────────────────────────
// 날짜 포맷
// ────────────────────────────────────────────────
const now  = new Date();
const days = ["일", "월", "화", "수", "목", "금", "토"];
const pad  = n => String(n).padStart(2, "0");
const dateStr = `${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())} (${days[now.getDay()]})`;

// ────────────────────────────────────────────────
// Slack 블록
// ────────────────────────────────────────────────
const newsText = articles.length > 0
  ? articles.slice(0, 5).map(a => `• <${a.link}|${a.title}>  _${a.source}_`).join("\n")
  : "_오늘은 관련 뉴스를 찾지 못했어요._";

const blocks = [
  {
    type: "header",
    text: { type: "plain_text", text: `🌅  모닝 브리핑  |  ${dateStr}` },
  },
  { type: "divider" },
  {
    type: "section",
    text: {
      type: "mrkdwn",
      text:
        "📋 *오늘의 대시보드*\n" +
        `• <${LINK_MISSION_BOARD}|미션 현황판>\n` +
        `• <${LINK_KDT_DASHBOARD}|KDT 대시보드>\n` +
        `• <${LINK_NOTION}|회의록 · 노션>`,
    },
  },
  { type: "divider" },
  {
    type: "section",
    text: {
      type: "mrkdwn",
      text: `📅 *모집 D-day 현황* (30일 이내)\n${ddayText}`,
    },
  },
  { type: "divider" },
  {
    type: "section",
    text: {
      type: "mrkdwn",
      text:
        `💡 *KDT 업계 현황 — ${dateStr} 기준*\n` +
        `${newsText}\n` +
        `_💬 자유롭게 아이디어 달아주세요!_`,
    },
  },
];

return [{ json: { text: `모닝 브리핑 | ${dateStr}`, blocks } }];
